package com.unimatrix.view;
import com.unimatrix.dao.*;
import com.unimatrix.service.*;
import com.unimatrix.model.*;
import javax.swing.*;
import javax.swing.table.*;
import java.awt.*;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.List;

/** Weekly windows plus date overrides; changes cannot invalidate a published timetable. */
final class AvailabilityPanel extends JPanel {
    final DefaultTableModel availability=new DefaultTableModel(new String[]{"ID","Faculty ID","Faculty","Weekday (1=Mon)","Exception date","Available","Start","End"},0){public boolean isCellEditable(int r,int c){return false;}};
    final DefaultTableModel excluded=new DefaultTableModel(new String[]{"Date","Reason"},0){public boolean isCellEditable(int r,int c){return false;}};
    final JTable windows=new JTable(availability),dates=new JTable(excluded);
    AvailabilityPanel(){super(new BorderLayout());JTabbedPane tabs=new JTabbedPane();tabs.addTab("Faculty availability",tab(windows,true));tabs.addTab("Excluded examination dates",tab(dates,false));add(tabs);SwingUtilities.invokeLater(this::reload);}
    JPanel tab(JTable table,boolean faculty){JPanel p=new JPanel(new BorderLayout());PlannerControls.stripes(table);p.add(new JScrollPane(table));JPanel buttons=BackgroundTask.bar();JButton add=new JButton("Add"),edit=new JButton("Edit"),delete=new JButton("Delete"),refresh=new JButton("Refresh");buttons.add(add);buttons.add(edit);buttons.add(delete);buttons.add(refresh);p.add(buttons,BorderLayout.SOUTH);add.addActionListener(e->form(faculty,-1));edit.addActionListener(e->{if(table.getSelectedRow()>=0)form(faculty,table.getSelectedRow());});delete.addActionListener(e->{int row=table.getSelectedRow();if(row<0)return;Object id=table.getValueAt(row,0);if(JOptionPane.showConfirmDialog(this,"Delete selected rule?","Delete rule",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;mutate(c->{try(PreparedStatement s=c.prepareStatement(faculty?"DELETE FROM faculty_availability WHERE id=?":"DELETE FROM excluded_dates WHERE exam_date=?")){s.setObject(1,id);s.executeUpdate();}return null;});});refresh.addActionListener(e->reload());return p;}
    void reload(){BackgroundTask.run(this,()->{List<Object[]> a=new ArrayList<>(),b=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();Statement s=c.createStatement()){
        try(ResultSet r=s.executeQuery("SELECT a.*,f.faculty_name FROM faculty_availability a JOIN faculty f ON f.id=a.faculty_id ORDER BY f.faculty_name,a.exception_date,a.weekday,a.start_time")){while(r.next())a.add(new Object[]{r.getInt("id"),r.getInt("faculty_id"),r.getString("faculty_name"),r.getObject("weekday"),r.getDate("exception_date"),r.getBoolean("available"),r.getTime("start_time"),r.getTime("end_time")});}
        try(ResultSet r=s.executeQuery("SELECT * FROM excluded_dates ORDER BY exam_date")){while(r.next())b.add(new Object[]{r.getDate(1),r.getString(2)});}}return List.of(a,b);},data->{availability.setRowCount(0);data.get(0).forEach(availability::addRow);excluded.setRowCount(0);data.get(1).forEach(excluded::addRow);});}
    void mutate(Transactions.Work<Void> work){BackgroundTask.run(this,()->Transactions.write(c->{work.run(c);List<Integer> ids=new ArrayList<>();try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id FROM schedule_files WHERE published=TRUE AND deleted=FALSE")){while(r.next())ids.add(r.getInt(1));}for(int id:ids)PlanningRules.validate(c,id,ScheduleEditorService.read(c,id).exams(),true);return true;}),ok->reload());}
    void form(boolean faculty,int row){BackgroundTask.run(this,()->new ScheduleEditorService().catalog(),catalog->{
        JComboBox<Faculty> person=new JComboBox<>(catalog.faculty().toArray(Faculty[]::new));JComboBox<String> weekday=new JComboBox<>(new String[]{"Date exception","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"});JCheckBox available=new JCheckBox("Available",true);JComboBox<String> start=PlannerControls.times(),end=PlannerControls.times();start.setSelectedItem("7:00 AM");end.setSelectedItem("9:00 PM");
        DefaultTableModel dm=new DefaultTableModel(new String[]{"Date"},1);JTable dateTable=new JTable(dm);PlannerControls.calendar(dateTable,0);dateTable.setRowHeight(32);JScrollPane datePane=new JScrollPane(dateTable);datePane.setPreferredSize(new Dimension(300,60));JTextField reason=new JTextField(25);
        if(row>=0){if(faculty){int fid=(Integer)availability.getValueAt(row,1);for(int i=0;i<person.getItemCount();i++)if(person.getItemAt(i).getId()==fid)person.setSelectedIndex(i);Object day=availability.getValueAt(row,3);weekday.setSelectedIndex(day==null?0:((Number)day).intValue());dm.setValueAt(Objects.toString(availability.getValueAt(row,4),""),0,0);available.setSelected((Boolean)availability.getValueAt(row,5));start.setSelectedItem(((Time)availability.getValueAt(row,6)).toLocalTime().format(java.time.format.DateTimeFormatter.ofPattern("h:mm a",Locale.ENGLISH)));end.setSelectedItem(((Time)availability.getValueAt(row,7)).toLocalTime().format(java.time.format.DateTimeFormatter.ofPattern("h:mm a",Locale.ENGLISH)));}else{dm.setValueAt(excluded.getValueAt(row,0).toString(),0,0);reason.setText(excluded.getValueAt(row,1).toString());}}
        Object[] fields=faculty?new Object[]{"Faculty",person,"Weekly day or date override",weekday,"Date (only for exception)",datePane,available,"Start",start,"End",end}:new Object[]{"Excluded date",datePane,"Reason",reason};
        if(JOptionPane.showConfirmDialog(this,fields,faculty?"Faculty availability":"Excluded examination date",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;
        try{if(!BackgroundTask.finishEdit(dateTable))return;LocalDate date=!faculty||weekday.getSelectedIndex()==0?LocalDate.parse(Objects.toString(dm.getValueAt(0,0),"")):null;
            if(faculty){Faculty selected=(Faculty)person.getSelectedItem();if(selected==null)throw new IllegalArgumentException("Add faculty first.");LocalTime from=ExamTimes.parse((String)start.getSelectedItem()),to=ExamTimes.parse((String)end.getSelectedItem());if(!to.isAfter(from))throw new IllegalArgumentException("End must follow start.");Integer day=weekday.getSelectedIndex()==0?null:weekday.getSelectedIndex();boolean permitted=available.isSelected();int id=row<0?0:(Integer)availability.getValueAt(row,0);
                mutate(c->{try(PreparedStatement p=c.prepareStatement(id==0?"INSERT INTO faculty_availability(faculty_id,weekday,exception_date,available,start_time,end_time) VALUES(?,?,?,?,?,?)":"UPDATE faculty_availability SET faculty_id=?,weekday=?,exception_date=?,available=?,start_time=?,end_time=? WHERE id=?")){p.setInt(1,selected.getId());p.setObject(2,day,Types.INTEGER);p.setObject(3,date==null?null:java.sql.Date.valueOf(date),Types.DATE);p.setBoolean(4,permitted);p.setTime(5,Time.valueOf(from));p.setTime(6,Time.valueOf(to));if(id!=0)p.setInt(7,id);p.executeUpdate();}return null;});
            }else{String text=reason.getText().trim();if(text.isEmpty()||text.length()>200)throw new IllegalArgumentException("Reason must contain 1-200 characters.");Object previous=row<0?null:excluded.getValueAt(row,0);mutate(c->{if(previous!=null)try(PreparedStatement p=c.prepareStatement("DELETE FROM excluded_dates WHERE exam_date=?")){p.setObject(1,previous);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("INSERT INTO excluded_dates(exam_date,reason) VALUES(?,?)")){p.setDate(1,java.sql.Date.valueOf(date));p.setString(2,text);p.executeUpdate();}return null;});}
        }catch(RuntimeException ex){BackgroundTask.error(this,ex);}
    });}
}
